1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
5	const HIGH_ENCHANTMENT_THRESHOLD = 5;
6	const LOYALTY_DISCOUNT_RATE = 0.2;
7	const LOYALTY_YEARS_THRESHOLD = 2;
8	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
9	
10	const COMPONENT_BASE_PREMIUM = 25;
11	const BLOCK_SIZE = 3;
12	const BLOCK_PREMIUM = 60;
13	
14	const DEDUCTIBLE = 100;
15	const CAP_MULTIPLIER = 2;
16	const REIMBURSEMENT_HIGH_ENCHANTMENT_THRESHOLD = 8;
17	const REIMBURSEMENT_HIGH_ENCHANTMENT_RATE = 0.5;
18	
19	const BASE_PREMIUM: Record<string, number> = {
20	  sword: 100,
21	  amulet: 60,
22	  staff: 80,
23	  potion: 40,
24	  rune: COMPONENT_BASE_PREMIUM,
25	  moonstone: COMPONENT_BASE_PREMIUM,
26	};
27	
28	const INSURANCE_VALUE: Record<string, number> = {
29	  sword: 1000,
30	  amulet: 600,
31	  staff: 800,
32	  potion: 400,
33	  rune: 250,
34	  moonstone: 250,
35	};
36	
37	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
38	
39	type Item = { type: string; cursed?: boolean; enchantment?: number; material?: string };
40	type Customer = { yearsWithMHPCO: number };
41	type Damage = { itemType: string; amount: number };
42	type QuoteStep = { op: "quote"; items: Item[] };
43	type ClaimStep = {
44	  op: "claim";
45	  policy: number;
46	  incident: { cause: string; damages: Damage[] };
47	};
48	type Step = QuoteStep | ClaimStep;
49	type Scenario = { customer: Customer; steps: Step[] };
50	
51	type QuoteResult = { premium: number };
52	type ClaimResult = { payout: number; remainingCap: number };
53	type StepResult = QuoteResult | ClaimResult;
54	
55	type PolicyState = { items: Item[]; insuranceSum: number; remainingCap: number };
56	
57	const countBy = <T>(values: T[], key: (value: T) => string): Map<string, number> =>
58	  values.reduce(
59	    (counts, value) => counts.set(key(value), (counts.get(key(value)) ?? 0) + 1),
60	    new Map<string, number>(),
61	  );
62	
63	const countsByType = (items: Item[]): Map<string, number> =>
64	  countBy(items, (item) => item.type);
65	
66	const groupBase = (type: string, count: number): number =>
67	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
68	    ? BLOCK_PREMIUM
69	    : count * BASE_PREMIUM[type];
70	
71	const itemsBase = (items: Item[]): number =>
72	  [...countsByType(items)].reduce(
73	    (total, [type, count]) => total + groupBase(type, count),
74	    0,
75	  );
76	
77	const isCursed = (item: Item): boolean => item.cursed === true;
78	const isHighlyEnchanted = (item: Item): boolean =>
79	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
80	
81	const SURCHARGE_RULES: Array<{ applies: (item: Item) => boolean; rate: number }> = [
82	  { applies: isCursed, rate: CURSE_SURCHARGE_RATE },
83	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
84	];
85	
86	const itemSurcharge = (item: Item): number => {
87	  const base = BASE_PREMIUM[item.type];
88	  return SURCHARGE_RULES.reduce(
89	    (sum, rule) => sum + (rule.applies(item) ? base * rule.rate : 0),
90	    0,
91	  );
92	};
93	
94	const itemSurchargesTotal = (items: Item[]): number =>
95	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
96	
97	const roundUpInFavorOfInsurer = (amount: number): number =>
98	  Math.ceil(Math.round(amount * 1e6) / 1e6);
99	
100	const roundDownInFavorOfInsurer = (amount: number): number =>
101	  Math.floor(Math.round(amount * 1e6) / 1e6);
102	
103	const isLoyal = (customer: Customer): boolean =>
104	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
105	
106	const loyaltyDiscount = (customer: Customer, policyBase: number): number =>
107	  isLoyal(customer) ? policyBase * LOYALTY_DISCOUNT_RATE : 0;
108	
109	const firstInsuranceSurcharge = (policyBase: number): number =>
110	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
111	
112	const followUpDiscount = (policyBase: number, isFollowUp: boolean): number =>
113	  isFollowUp ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0;
114	
115	const validateItems = (items: Item[]): void => {
116	  const unknown = items.find((item) => !(item.type in BASE_PREMIUM));
117	  if (unknown) throw new Error(`unknown item type: ${unknown.type}`);
118	};
119	
120	const quotePremium = (items: Item[], customer: Customer, isFollowUp: boolean): number => {
121	  validateItems(items);
122	  const policyBase = itemsBase(items);
123	  return roundUpInFavorOfInsurer(
124	    policyBase +
125	      itemSurchargesTotal(items) +
126	      firstInsuranceSurcharge(policyBase) -
127	      loyaltyDiscount(customer, policyBase) -
128	      followUpDiscount(policyBase, isFollowUp) +
129	      PROCESSING_FEE,
130	  );
131	};
132	
133	const insuranceSum = (items: Item[]): number =>
134	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
135	
136	const createPolicy = (items: Item[]): PolicyState => {
137	  const sum = insuranceSum(items);
138	  return { items, insuranceSum: sum, remainingCap: sum * CAP_MULTIPLIER };
139	};
140	
141	const reimbursementRate = (item: Item): number =>
142	  (item.enchantment ?? 0) >= REIMBURSEMENT_HIGH_ENCHANTMENT_THRESHOLD
143	    ? REIMBURSEMENT_HIGH_ENCHANTMENT_RATE
144	    : 1;
145	
146	const damagePayout = (damage: Damage, damagedItem: Item): number =>
147	  damage.amount * reimbursementRate(damagedItem) - DEDUCTIBLE;
148	
149	const findDamagedItem = (policy: PolicyState, itemType: string): Item =>
150	  policy.items.find((i) => i.type === itemType)!;
151	
152	const payoutForDamage = (policy: PolicyState, damage: Damage): number =>
153	  damagePayout(damage, findDamagedItem(policy, damage.itemType));
154	
155	const validateDamages = (damages: Damage[], policy: PolicyState): void => {
156	  const negative = damages.find((damage) => damage.amount < 0);
157	  if (negative) throw new Error(`negative damage amount: ${negative.amount}`);
158	
159	  const damageCounts = countBy(damages, (damage) => damage.itemType);
160	  const insuredCounts = countsByType(policy.items);
161	  damageCounts.forEach((count, type) => {
162	    if (count > (insuredCounts.get(type) ?? 0)) {
163	      throw new Error(`damage for ${type} exceeds insured count`);
164	    }
165	  });
166	};
167	
168	const totalDesiredPayout = (policy: PolicyState, damages: Damage[]): number =>
169	  damages.reduce((sum, damage) => sum + payoutForDamage(policy, damage), 0);
170	
171	const processClaim = (policy: PolicyState, damages: Damage[]): ClaimResult => {
172	  validateDamages(damages, policy);
173	  const desired = totalDesiredPayout(policy, damages);
174	  const payout = roundDownInFavorOfInsurer(Math.min(desired, policy.remainingCap));
175	  policy.remainingCap -= payout;
176	  return { payout, remainingCap: policy.remainingCap };
177	};
178	
179	export const runScenario = (scenario: unknown): unknown => {
180	  const s = scenario as Scenario;
181	  const policies = new Map<number, PolicyState>();
182	  let quoteCount = 0;
183	  const results: StepResult[] = s.steps.map((step, index) => {
184	    if (step.op === "quote") {
185	      const isFollowUp = quoteCount > 0;
186	      quoteCount += 1;
187	      policies.set(index, createPolicy(step.items));
188	      return { premium: quotePremium(step.items, s.customer, isFollowUp) };
189	    }
190	    const policy = policies.get(step.policy)!;
191	    return processClaim(policy, step.incident.damages);
192	  });
193	  return { results };
194	};
