3	const readStdin = (): Promise<string> =>
4	  new Promise((resolve, reject) => {
5	    let data = "";
6	    process.stdin.setEncoding("utf8");
7	    process.stdin.on("data", (chunk) => {
8	      data += chunk;
9	    });
10	    process.stdin.on("end", () => resolve(data));
11	    process.stdin.on("error", reject);
12	  });
13	
14	const main = async (): Promise<void> => {
15	  const input = await readStdin();
16	  try {
17	    const scenario = JSON.parse(input);
18	    const result = runScenario(scenario);
19	    process.stdout.write(JSON.stringify(result));
20	  } catch (err) {
21	    process.stderr.write(`${(err as Error).message}\n`);
22	    process.exit(1);
23	  }
24	};
25	
26	main();
